class Solution {
  private static final long M1 = 1_000_000_007L, M2 = 998_244_353L;

  public int smallestUniqueSubarray(int[] nums) {
    int n = nums.length;
    long[] pre1 = new long[n + 1],
        pre2 = new long[n + 1],
        pow1 = new long[n + 1],
        pow2 = new long[n + 1];
    pow1[0] = pow2[0] = 1;
    for (int i = 0; i < n; i++) {
      pow1[i + 1] = pow1[i] * 131 % M1;
      pow2[i + 1] = pow2[i] * 137 % M2;
      pre1[i + 1] = (pre1[i] * 131 + nums[i]) % M1;
      pre2[i + 1] = (pre2[i] * 137 + nums[i]) % M2;
    }
    int lo = 1, hi = n;
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      java.util.HashMap<Long, Integer> count = new java.util.HashMap<>();
      for (int i = 0; i + mid <= n; i++) {
        long h1 = ((pre1[i + mid] - pre1[i] * pow1[mid]) % M1 + M1) % M1;
        long h2 = ((pre2[i + mid] - pre2[i] * pow2[mid]) % M2 + M2) % M2;
        count.merge(h1 << 32 | h2, 1, Integer::sum);
      }
      boolean unique = false;
      for (int c : count.values())
        if (c == 1) {
          unique = true;
          break;
        }
      if (unique) hi = mid;
      else lo = mid + 1;
    }
    return lo;
  }
}
